# [LATER-STEP] unsafe_copy_check.py – Check localized copy for unsafe content\n# Uses watsonx.ai guardrails / HAP detection (concrete provider)\nimport os\nimport requests\nfrom typing import List, Dict\n\n# Provider‑specific signal\nWATSONX_API_KEY = os.getenv('WATSONX_API_KEY')\nWATSONX_PROJECT_ID = os.getenv('WATSONX_PROJECT_ID')\nif not (WATSONX_API_KEY and WATSONX_PROJECT_ID):\n    raise RuntimeError('Set WATSONX_API_KEY and WATSONX_PROJECT_ID environment variables.')\n\nBASE_URL = 'https://api.us-south.watsonx.ibm.com/v1/guardrails'\n\nHEADERS = {\n    'Authorization': f'apikey {WATSONX_API_KEY}',\n    'Content-Type': 'application/json',\n}\n\ndef check_unsafe(content: List[str]) -> List[Dict[str, Any]]:\n    \"\"\"Run the watsonx Guardrails API (HAP / toxicity detection) on a list of strings.\n\n    Returns a list of dicts, one per input string, containing:\n        * \"content\": original text\n        * \"safe\": boolean flag\n        * \"issues\": list of detected issue categories (e.g., hate, self_harm, etc.)\n    \"\"\"\n    payload = {\n        'inputs': [{\"text\": txt} for txt in content],\n        'configuration': {\n            'moderation': {\n                'categories': ['hate', 'self_harm', 'sexual', 'violence', 'hate_group']\n            }\n        }\n    }\n    resp = requests.post(f\"{BASE_URL}/moderation\", headers=HEADERS, json=payload)\n    resp.raise_for_status()\n    result = resp.json()\n    # Normalize response to desired shape\n    output = []\n    for idx, item in enumerate(result.get('results', [])):\n        out = {\n            'content': content[idx],\n            'safe': item.get('safe', False),\n            'issues': [issue['category'] for issue in item.get('issues', [])]\n        }\n        output.append(out)\n    return output\n\n# Example usage\nif __name__ == '__main__':\n    sample = [\n        'This is a safe sentence.',\n        'Buy illegal drugs now!',\n        'Hate speech is terrible.',\n    ]\n    print(check_unsafe(sample))